#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n;
    // 至少一天，第一天自身构成长度1的合法连续段。
    scanf("%d", &n);
    long long previous, value;
    scanf("%lld", &previous);
    int current = 1, best = 1;
    for (int i = 1; i < n; ++i) {
        scanf("%lld", &value);
        // 相等也可延长；真正下降时从今天重新开始为长度1。
        current = value >= previous ? current + 1 : 1;
        if (current > best) {
            best = current;
        }
        // 比较后再覆盖前一天分数，下一轮才能比较相邻两天。
        previous = value;
    }
    // 输出历史最长段，不是仅输出结尾的current。
    printf("%d\n", best);
    return 0;
}

