use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    // 至少一天，第一天自身构成长度1的合法连续段。
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut previous: i64 = tokens.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut best = 1usize;
    for _ in 1..n {
        let value: i64 = tokens.next().unwrap().parse().unwrap();
        // 相等也可延长；真正下降时从今天重新开始为长度1。
        current = if value >= previous { current + 1 } else { 1 };
        best = best.max(current);
        // 比较后再覆盖前一天分数，下一轮才能比较相邻两天。
        previous = value;
    }
    // 输出历史最长段，不是仅输出结尾的current。
    println!("{}", best);
}
